from functools import lru_cache

data = list(map(int, input().split()))
n, m = data[0], data[1]
broken = set(data[2:2 + m])

@lru_cache(None)
def ways(k):
    if k < 0 or k in broken:
        return 0
    if k == 0:
        return 1
    return ways(k - 1) + ways(k - 2) + ways(k - 3)

print(ways(n))

