from functools import lru_cache

r, c = map(int, input().split())

# (0, 0)에서 (i, j)칸까지 오른쪽이나 아래로만 가는 길의 수예요.
@lru_cache(None)
def paths(i, j):
    # 첫 줄이나 첫 열에서는 갈 수 있는 길이 하나뿐이에요.
    if i == 0 or j == 0:
        return 1
    # 위에서 내려오는 길과 왼쪽에서 오는 길을 합해요.
    return paths(i - 1, j) + paths(i, j - 1)

# 저장해 둔 값을 다시 쓰니 큰 칸도 금방 계산돼요.
print(paths(r, c))
